import React from "react";
import Link from "next/link";
import { clsx } from "clsx";

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: "gradient" | "secondary" | "outline" | "ghost" | "glass";
  size?: "sm" | "md" | "lg";
  href?: string;
  icon?: React.ReactNode;
  iconPosition?: "left" | "right";
  children: React.ReactNode;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      variant = "gradient",
      size = "md",
      href,
      icon,
      iconPosition = "right",
      className,
      children,
      disabled,
      ...props
    },
    ref
  ) => {
    const baseStyles =
      "inline-flex items-center justify-center font-medium transition-all duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-indigo-400 focus-visible:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none select-none active:scale-[0.98]";

    const sizeStyles = {
      sm: "text-xs px-3.5 py-1.5 rounded-xl gap-1.5",
      md: "text-sm px-5 py-2.5 rounded-2xl gap-2 font-semibold",
      lg: "text-base px-6 py-3.5 rounded-2xl gap-2.5 font-semibold",
    };

    const variantStyles = {
      gradient: "button-gradient text-white shadow-md shadow-indigo-500/20",
      secondary:
        "bg-white/10 hover:bg-white/15 text-white border border-white/15 backdrop-blur-sm",
      outline:
        "border border-slate-200 dark:border-white/15 text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-white/5",
      ghost: "text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-white/10",
      glass:
        "bg-white/8 hover:bg-white/12 text-white border border-white/10 backdrop-blur-md shadow-sm",
    };

    const combinedClasses = clsx(
      baseStyles,
      sizeStyles[size],
      variantStyles[variant],
      className
    );

    const innerContent = (
      <>
        {icon && iconPosition === "left" && <span className="shrink-0">{icon}</span>}
        <span>{children}</span>
        {icon && iconPosition === "right" && <span className="shrink-0">{icon}</span>}
      </>
    );

    if (href) {
      return (
        <Link href={href} className={combinedClasses}>
          {innerContent}
        </Link>
      );
    }

    return (
      <button ref={ref} className={combinedClasses} disabled={disabled} {...props}>
        {innerContent}
      </button>
    );
  }
);

Button.displayName = "Button";
