"use client";

import React, { useState } from "react";
import Link from "next/link";
import {
  ChevronRight,
  Zap,
  ShieldCheck,
  Heart,
  Laptop,
  Lightbulb,
  ArrowRight,
  Sparkles,
} from "lucide-react";
import { ToolCategory } from "@/data/categories";
import { Tool } from "@/data/tools";
import { ToolCard } from "@/components/tools/ToolCard";
import { ToolSearch } from "@/components/tools/ToolSearch";
import { Button } from "@/components/ui/Button";
import { CategoryHeroVisual } from "./CategoryHeroVisual";

interface CategoryPageClientProps {
  category: ToolCategory;
  tools: Tool[];
}

export function CategoryPageClient({ category, tools }: CategoryPageClientProps) {
  const [activeFilter, setActiveFilter] = useState("all");
  const [searchQuery, setSearchQuery] = useState("");

  const filterTabs = [
    { id: "all", label: "All Tools" },
    { id: "popular", label: "Popular" },
    { id: "convert", label: "Convert" },
    { id: "edit", label: "Edit" },
    { id: "optimize", label: "Optimize" },
  ];

  // Filter tools based on active tab and local search query
  const filteredTools = tools.filter((tool) => {
    // Filter by tab
    if (activeFilter === "popular" && !tool.popular) return false;
    if (
      activeFilter !== "all" &&
      activeFilter !== "popular" &&
      tool.subCategory !== activeFilter
    ) {
      return false;
    }
    // Filter by query
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      return (
        tool.name.toLowerCase().includes(q) ||
        tool.description.toLowerCase().includes(q) ||
        tool.tags.some((t) => t.toLowerCase().includes(q))
      );
    }
    return true;
  });

  const valueBadges = [
    { icon: Zap, label: "Fast", color: "text-amber-400" },
    { icon: ShieldCheck, label: "Privacy-first", color: "text-emerald-400" },
    { icon: Heart, label: "Free to Use", color: "text-pink-400" },
    { icon: Laptop, label: "Works on All Devices", color: "text-blue-400" },
  ];

  return (
    <div className="w-full">
      {/* Category Dark Hero Section */}
      <section className="relative w-full bg-[#070B24] hero-glow pt-28 pb-20 md:pt-36 md:pb-28 text-white overflow-hidden">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
          {/* Breadcrumbs */}
          <nav className="flex items-center gap-2 text-xs text-white/60 mb-6" aria-label="Breadcrumb">
            <Link href="/" className="hover:text-white transition-colors">
              Home
            </Link>
            <ChevronRight className="w-3.5 h-3.5 text-white/40" />
            <span className="text-white/90 font-medium">{category.name}</span>
          </nav>

          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 items-center">
            {/* Left Header */}
            <div className="lg:col-span-7 flex flex-col items-start">
              {/* Category Pill */}
              <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/10 border border-white/15 text-[11px] font-bold uppercase tracking-widest text-indigo-300 mb-4 backdrop-blur-md">
                {category.name}
              </div>

              {/* Title */}
              <h1 className="text-4xl sm:text-5xl md:text-6xl font-extrabold tracking-tight leading-tight mb-5">
                {category.shortName}{" "}
                <span className="text-gradient-hero">Tools</span>
              </h1>

              {/* Description */}
              <p className="text-base sm:text-lg text-white/75 max-w-xl mb-7 leading-relaxed">
                {category.description} Everything you need to get fast, private, and reliable results directly in your browser.
              </p>

              {/* Trust Badges */}
              <div className="flex flex-wrap items-center gap-2.5">
                {valueBadges.map((badge) => {
                  const Icon = badge.icon;
                  return (
                    <div
                      key={badge.label}
                      className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-white/8 border border-white/10 text-xs font-medium text-white/85 backdrop-blur-sm"
                    >
                      <Icon className={`w-3.5 h-3.5 ${badge.color}`} />
                      <span>{badge.label}</span>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Right Visual */}
            <div className="lg:col-span-5 flex items-center justify-center">
              <CategoryHeroVisual categorySlug={category.slug} />
            </div>
          </div>
        </div>

        {/* Curved transition to white surface */}
        <div className="absolute bottom-0 left-0 right-0 h-10 md:h-14 bg-[#F7F8FC] rounded-t-[36px] sm:rounded-t-[48px] pointer-events-none" />
      </section>

      {/* Main Content Area */}
      <section className="w-full bg-[#F7F8FC] pb-24 pt-4">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          {/* Search bar + New Here Tip Banner Row */}
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 items-center mb-10">
            <div className="lg:col-span-7">
              <div className="relative w-full">
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder={`Search ${category.shortName.toLowerCase()} tools (e.g. compress, resize, convert...)`}
                  className="w-full px-5 py-3.5 pl-12 rounded-full bg-white border border-slate-200/80 shadow-sm text-sm text-[#111936] placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-indigo-400"
                />
                <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
                  <Zap className="w-4 h-4" />
                </div>
              </div>
            </div>

            <div className="lg:col-span-5">
              <div className="flex items-center justify-between p-3.5 px-4 bg-white rounded-2xl border border-amber-200/60 shadow-sm">
                <div className="flex items-center gap-3">
                  <span className="text-xl">💡</span>
                  <div>
                    <span className="text-xs font-bold text-[#111936] block">
                      New here?
                    </span>
                    <span className="text-xs text-slate-500">
                      Find the perfect tool for your {category.shortName.toLowerCase()} task.
                    </span>
                  </div>
                </div>
                <Button href="/about" size="sm" variant="gradient" className="shrink-0 text-xs">
                  View Guide &rarr;
                </Button>
              </div>
            </div>
          </div>

          {/* Section Header & Filter Pills */}
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8">
            <div>
              <h2 className="text-2xl sm:text-3xl font-extrabold text-[#111936]">
                All {category.shortName}{" "}
                <span className="text-gradient-purple">Tools</span>
              </h2>
              <p className="text-xs sm:text-sm text-slate-500 mt-1">
                Choose a tool below to get started. More tools coming soon!
              </p>
            </div>

            {/* Filter Pills */}
            <div className="flex flex-wrap items-center gap-1.5 p-1 bg-slate-200/60 rounded-2xl">
              {filterTabs.map((tab) => (
                <button
                  key={tab.id}
                  onClick={() => setActiveFilter(tab.id)}
                  className={`px-3.5 py-1.5 rounded-xl text-xs font-semibold transition-all ${
                    activeFilter === tab.id
                      ? "bg-indigo-600 text-white shadow-sm"
                      : "text-slate-600 hover:text-slate-900 hover:bg-white/50"
                  }`}
                >
                  {tab.label}
                </button>
              ))}
            </div>
          </div>

          {/* Tools Grid */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 md:gap-6 mb-16">
            {filteredTools.map((tool) => (
              <ToolCard key={tool.slug} tool={tool} />
            ))}

            {/* More Coming Soon Card */}
            <div className="flex flex-col justify-between p-6 bg-white/70 rounded-2xl md:rounded-3xl border border-dashed border-slate-300 text-slate-400">
              <div>
                <div className="w-12 h-12 rounded-2xl bg-slate-100 flex items-center justify-center text-slate-400 mb-4">
                  <Sparkles className="w-6 h-6" />
                </div>
                <h3 className="text-base font-bold text-slate-700 mb-1">
                  More Coming Soon
                </h3>
                <p className="text-xs text-slate-500">
                  We are adding more {category.shortName.toLowerCase()} tools regularly to the Zorli platform.
                </p>
              </div>
              <div className="mt-5 pt-3 border-t border-slate-100 text-[11px] font-medium text-slate-400">
                In Active Development
              </div>
            </div>
          </div>

          {/* Why Zorli Dark Banner (Matching Image 2) */}
          <div className="w-full bg-[#0D1438] rounded-3xl p-6 sm:p-10 text-white mb-10 shadow-xl border border-white/10">
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-center">
              <div className="lg:col-span-5">
                <span className="text-xs font-bold uppercase tracking-wider text-indigo-400 block mb-2">
                  WHY ZORLI?
                </span>
                <h3 className="text-2xl sm:text-3xl font-extrabold tracking-tight mb-3">
                  Powerful {category.shortName} Tools, <br />
                  Built for <span className="text-gradient-hero">You.</span>
                </h3>
                <p className="text-sm text-white/70 leading-relaxed">
                  Simple. Fast. Private. Everything you need, nothing you don&apos;t.
                </p>
              </div>

              <div className="lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="flex items-start gap-3.5 p-4 rounded-2xl bg-white/5 border border-white/10">
                  <div className="p-2.5 rounded-xl bg-purple-500/20 text-purple-300">
                    <Zap className="w-5 h-5" />
                  </div>
                  <div>
                    <h4 className="text-sm font-bold text-white">Lightning Fast</h4>
                    <p className="text-xs text-white/60 mt-0.5">Get results in seconds.</p>
                  </div>
                </div>

                <div className="flex items-start gap-3.5 p-4 rounded-2xl bg-white/5 border border-white/10">
                  <div className="p-2.5 rounded-xl bg-emerald-500/20 text-emerald-300">
                    <ShieldCheck className="w-5 h-5" />
                  </div>
                  <div>
                    <h4 className="text-sm font-bold text-white">Your Privacy Matters</h4>
                    <p className="text-xs text-white/60 mt-0.5">Files stay on your device.</p>
                  </div>
                </div>

                <div className="flex items-start gap-3.5 p-4 rounded-2xl bg-white/5 border border-white/10">
                  <div className="p-2.5 rounded-xl bg-rose-500/20 text-rose-300">
                    <Heart className="w-5 h-5" />
                  </div>
                  <div>
                    <h4 className="text-sm font-bold text-white">Completely Free</h4>
                    <p className="text-xs text-white/60 mt-0.5">No sign-ups. No limits.</p>
                  </div>
                </div>

                <div className="flex items-start gap-3.5 p-4 rounded-2xl bg-white/5 border border-white/10">
                  <div className="p-2.5 rounded-xl bg-blue-500/20 text-blue-300">
                    <Laptop className="w-5 h-5" />
                  </div>
                  <div>
                    <h4 className="text-sm font-bold text-white">Works Everywhere</h4>
                    <p className="text-xs text-white/60 mt-0.5">On any device, anytime.</p>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Pro Tip Banner (Matching Image 2) */}
          <div className="w-full flex flex-col sm:flex-row items-center justify-between p-6 sm:p-8 bg-white rounded-3xl border border-slate-200/80 shadow-sm gap-6">
            <div className="flex items-center gap-4">
              <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-blue-100 to-indigo-100 text-indigo-600 flex items-center justify-center shrink-0">
                <Sparkles className="w-7 h-7" />
              </div>
              <div>
                <span className="text-base font-bold text-[#111936] block mb-1">
                  Pro Tip
                </span>
                <p className="text-sm text-slate-600">
                  Need a smaller image for a form or website? Try our{" "}
                  <strong className="text-[#111936]">Image Compressor</strong> — it&apos;s our most popular tool!
                </p>
              </div>
            </div>

            <Button
              href="/tools/image-compressor"
              size="md"
              variant="gradient"
              icon={<ArrowRight className="w-4 h-4" />}
              className="shrink-0"
            >
              Try Image Compressor
            </Button>
          </div>
        </div>
      </section>
    </div>
  );
}

export default CategoryPageClient;
